import sqlite3
from typing import Optional
from fastapi import FastAPI, HTTPException, status, Query
from fastapi.responses import HTMLResponse
from pydantic import BaseModel, Field

def init_db(database_path: str):
    conn = sqlite3.connect(database_path)
    cursor = conn.cursor()
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS tasks (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'todo'
        )
    """)
    conn.commit()
    conn.close()

class TaskCreate(BaseModel):
    title: str

class TaskUpdate(BaseModel):
    title: Optional[str] = None
    status: Optional[str] = None

def create_app(database_path: str = "tasks.db") -> FastAPI:
    init_db(database_path)
    app = FastAPI()

    @app.post("/tasks", status_code=status.HTTP_201_CREATED)
    def create_task(task: TaskCreate):
        if not isinstance(task.title, str) or not task.title.strip():
            raise HTTPException(status_code=422, detail="Title cannot be blank")
        conn = sqlite3.connect(database_path)
        cursor = conn.cursor()
        cursor.execute("INSERT INTO tasks (title, status) VALUES (?, ?)", (task.title, "todo"))
        conn.commit()
        task_id = cursor.lastrowid
        cursor.execute("SELECT id, title, status FROM tasks WHERE id = ?", (task_id,))
        row = cursor.fetchone()
        conn.close()
        return {"id": row[0], "title": row[1], "status": row[2]}

    @app.get("/tasks")
    def list_tasks(
        q: Optional[str] = Query(None),
        status: Optional[str] = Query(None)
    ):
        conn = sqlite3.connect(database_path)
        cursor = conn.cursor()
        query = "SELECT id, title, status FROM tasks WHERE 1=1"
        params = []
        
        if q is not None:
            query += " AND LOWER(title) LIKE ? ESCAPE '\\'"
            escaped_q = q.lower().replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')
            params.append(f"%{escaped_q}%")
            
        if status is not None:
            if status not in ("todo", "in_progress", "done"):
                conn.close()
                raise HTTPException(status_code=422, detail="Invalid status")
            query += " AND status = ?"
            params.append(status)
            
        query += " ORDER BY id ASC"
        cursor.execute(query, params)
        rows = cursor.fetchall()
        conn.close()
        return [{"id": r[0], "title": r[1], "status": r[2]} for r in rows]

    @app.patch("/tasks/{task_id}")
    def update_task(task_id: int, task_update: TaskUpdate):
        if task_update.title is None and task_update.status is None:
            raise HTTPException(status_code=422, detail="Empty update")
            
        if task_update.title is not None:
            if not isinstance(task_update.title, str) or not task_update.title.strip():
                raise HTTPException(status_code=422, detail="Title cannot be blank")
                
        if task_update.status is not None:
            if task_update.status not in ("todo", "in_progress", "done"):
                raise HTTPException(status_code=422, detail="Invalid status")

        conn = sqlite3.connect(database_path)
        cursor = conn.cursor()
        cursor.execute("SELECT id, title, status FROM tasks WHERE id = ?", (task_id,))
        row = cursor.fetchone()
        if not row:
            conn.close()
            raise HTTPException(status_code=404, detail="Task not found")

        current_title, current_status = row[1], row[2]
        new_title = task_update.title if task_update.title is not None else current_title
        new_status = task_update.status if task_update.status is not None else current_status

        cursor.execute("UPDATE tasks SET title = ?, status = ? WHERE id = ?", (new_title, new_status, task_id))
        conn.commit()
        cursor.execute("SELECT id, title, status FROM tasks WHERE id = ?", (task_id,))
        updated_row = cursor.fetchone()
        conn.close()
        return {"id": updated_row[0], "title": updated_row[1], "status": updated_row[2]}

    @app.delete("/tasks/{task_id}", status_code=status.HTTP_204_NO_CONTENT)
    def delete_task(task_id: int):
        conn = sqlite3.connect(database_path)
        cursor = conn.cursor()
        cursor.execute("SELECT id FROM tasks WHERE id = ?", (task_id,))
        row = cursor.fetchone()
        if not row:
            conn.close()
            raise HTTPException(status_code=404, detail="Task not found")
        cursor.execute("DELETE FROM tasks WHERE id = ?", (task_id,))
        conn.commit()
        conn.close()
        return None

    @app.get("/", response_class=HTMLResponse)
    def web_interface():
        html_content = """<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Mini Task Manager</title>
    <style>
        body { font-family: sans-serif; max-width: 800px; margin: 2rem auto; padding: 0 1rem; }
        .error { color: red; margin-bottom: 1rem; }
        .task-item { display: flex; justify-content: space-between; align-items: center; padding: 0.5rem; border-bottom: 1px solid #ddd; }
        .task-actions button { margin-left: 0.5rem; }
        .controls { display: flex; gap: 1rem; margin-bottom: 1rem; }
    </style>
</head>
<body>
    <main>
        <h1>Mini Task Manager</h1>
        <div id="error-box" class="error"></div>
        <form id="create-form">
            <label for="new-title">New Task</label>
            <input type="text" id="new-title" placeholder="New task title..." required>
            <button type="submit">Add Task</button>
        </form>
        <div class="controls" style="margin-top: 1rem;">
            <label for="search-q">Search</label>
            <input type="text" id="search-q" placeholder="Search tasks...">
            <label for="filter-status">Status</label>
            <select id="filter-status">
                <option value="">All Statuses</option>
                <option value="todo">Todo</option>
                <option value="in_progress">In Progress</option>
                <option value="done">Done</option>
            </select>
            <button id="search-btn">Filter</button>
        </div>
        <div id="task-list"></div>
    </main>
    <script>
        async function fetchTasks() {
            const q = document.getElementById('search-q').value;
            const status = document.getElementById('filter-status').value;
            let url = '/tasks?';
            if (q) url += `q=${encodeURIComponent(q)}&`;
            if (status) url += `status=${encodeURIComponent(status)}`;
            
            const res = await fetch(url);
            const tasks = await res.json();
            const listEl = document.getElementById('task-list');
            listEl.innerHTML = '';
            tasks.forEach(task => {
                const div = document.createElement('div');
                div.className = 'task-item';
                
                const label = document.createElement('label');
                label.className = 'task-title';
                label.textContent = task.title + ' (' + task.status + ')';
                div.appendChild(label);

                const actions = document.createElement('div');
                actions.className = 'task-actions';

                const statusSelect = document.createElement('select');
                statusSelect.setAttribute('aria-label', 'Task Status');
                ['todo', 'in_progress', 'done'].forEach(st => {
                    const opt = document.createElement('option');
                    opt.value = st;
                    opt.textContent = st;
                    if (st === task.status) opt.selected = true;
                    statusSelect.appendChild(opt);
                });
                statusSelect.onchange = async () => {
                    const r = await fetch(`/tasks/${task.id}`, {
                        method: 'PATCH',
                        headers: {'Content-Type': 'application/json'},
                        body: JSON.stringify({status: statusSelect.value})
                    });
                    if (!r.ok) showError('Failed to update status');
                    else fetchTasks();
                };
                actions.appendChild(statusSelect);

                const editBtn = document.createElement('button');
                editBtn.textContent = 'Edit';
                editBtn.onclick = async () => {
                    const newTitle = prompt('Edit task title:', task.title);
                    if (newTitle !== null) {
                        const r = await fetch(`/tasks/${task.id}`, {
                            method: 'PATCH',
                            headers: {'Content-Type': 'application/json'},
                            body: JSON.stringify({title: newTitle})
                        });
                        if (!r.ok) {
                            const err = await r.json();
                            showError(err.detail || 'Failed to edit');
                        } else {
                            fetchTasks();
                        }
                    }
                };
                actions.appendChild(editBtn);

                const delBtn = document.createElement('button');
                delBtn.textContent = 'Delete';
                delBtn.onclick = async () => {
                    const r = await fetch(`/tasks/${task.id}`, {method: 'DELETE'});
                    if (!r.ok) showError('Failed to delete');
                    else fetchTasks();
                };
                actions.appendChild(delBtn);

                div.appendChild(actions);
                listEl.appendChild(div);
            });
        }

        function showError(msg) {
            document.getElementById('error-box').textContent = msg;
        }

        document.getElementById('create-form').onsubmit = async (e) => {
            e.preventDefault();
            showError('');
            const title = document.getElementById('new-title').value;
            const r = await fetch('/tasks', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({title})
            });
            if (!r.ok) {
                const err = await r.json();
                showError(err.detail || 'Failed to create');
            } else {
                document.getElementById('new-title').value = '';
                fetchTasks();
            }
        };

        document.getElementById('search-btn').onclick = fetchTasks;
        fetchTasks();
    </script>
</body>
</html>
"""
        return HTMLResponse(content=html_content)

    return app


